// Measured screen fit from evidence/verified-10.png. This is an affine preview,
// not an emulation of Warcraft's unit clipping, terrain or text-tag renderer.
export const dialogueModel=Object.freeze({width:140,height:140*809/1942,textureWidth:1024,textureHeight:512,artWidth:1942,artHeight:809,alphaBounds:[63,47,1876,763]});
// Camera.win2World constants and measured UIText client mapping. One shared
// transform for the frame and text; not a simulation of unit rendering.
export const cameraPlane=Object.freeze({screenWidth:.544,screenHeight:.302,originX:960,originY:420,unitX:728,unitY:390,hudTop:78});
export function cameraFrame(plane){
 const width=plane.width*19.2,center=(plane.top+plane.height/2)*10.8;
 return {anchorX:((plane.left+plane.width/2)*19.2-cameraPlane.originX)/cameraPlane.unitX,anchorY:(cameraPlane.originY-center)/cameraPlane.unitY,nativeScale:width/cameraPlane.unitX*cameraPlane.screenWidth*plane.depth/dialogueModel.width};
}
// Measured model rendering in the calibrated gameplay camera at 1920x1080.
// UIText has a different client fit; this changes preview art only, never JASS.
export const modelCameraPlane=Object.freeze({"id":"classic127b-gameplay-1920x1080-20261022","originX":961,"originY":432.3236690135403,"unitX":718.1893054298849,"unitY":387.7381926120089});
export function modelPreviewRect(plane){
 const f=cameraFrame(plane),m=modelCameraPlane;
 const width=f.nativeScale*dialogueModel.width*m.unitX/(cameraPlane.screenWidth*plane.depth);
 const height=f.nativeScale*dialogueModel.height*m.unitY/(cameraPlane.screenHeight*plane.depth);
 const cx=m.originX+f.anchorX*m.unitX,cy=m.originY-f.anchorY*m.unitY;
 return {left:cx-width/2,top:cy-height/2,width,height};
}
export const calibrationPreset=()=>({version:1,planeWidth:91.5,planeHeight:64.7,planeTop:12.8,depth:400,frustumWidth:.81,centerY:-.49,source:'verified-10 / 1920x1080; one camera position'});
export function validateCalibration(c){
 if(!c||c.version!==1)throw Error('Perfil de calibración inválido.');
 for(const [key,min,max] of [['planeWidth',30,150],['planeHeight',20,120],['planeTop',-50,80],['depth',100,2000],['frustumWidth',.2,1.5],['centerY',-2,2]])if(!Number.isFinite(c[key])||c[key]<min||c[key]>max)throw Error('Calibración fuera de rango: '+key);
 if(typeof c.source!=='string'||c.source.length>160)throw Error('Procedencia de calibración inválida.');
 return c;
}
export function dialogueProjection(d){
 const c=validateCalibration(d.calibration??calibrationPreset()),ratio=d.layout.width/84.6;
 if(d.viewport==='gameplay'){
  const width=c.planeWidth*ratio*(c.frustumWidth/.81);
  const height=width*19.2*dialogueModel.height/dialogueModel.width*(cameraPlane.unitY/cameraPlane.screenHeight)/(cameraPlane.unitX/cameraPlane.screenWidth)/10.8;
  const top=cameraPlane.hudTop-4-d.layout.bottom-height;
  const p={left:(100-width)/2,top,width,height,depth:c.depth,frustumWidth:c.frustumWidth*ratio,centerY:0,scale:0,clipped:top<0||top+height>cameraPlane.hudTop||width>100};
  const frame=cameraFrame(p);return {...p,...frame,scale:frame.nativeScale,centerY:frame.anchorY};
 }
 const zoom=c.frustumWidth/.81;
 const width=c.planeWidth*ratio*zoom,height=c.planeHeight*ratio*zoom;
 const top=c.planeTop+c.planeHeight-height-(d.layout.bottom-6)-(c.centerY+.49)*31.75;
 // Affine displacement measured from two captures of the same local camera.
 // Remains provisional until the clipping defect at the other start is fixed.
 const centerY=c.centerY+((d.layout.bottom-6)+(height-c.planeHeight)/2)/31.75;
 const frustumWidth=c.frustumWidth*ratio;
 const scale=2*c.depth*Math.tan(70*Math.PI/360)*frustumWidth/dialogueModel.width;
 const p={left:(100-width)/2,top,width,height,depth:c.depth,frustumWidth,centerY,scale,clipped:top<0||top+height>100||width>100};return {...p,...cameraFrame(p)};
}
export function projectionJass(d){const p=dialogueProjection(d);return `// Generated by UI Studio; affine calibration remains provisional.\nlibrary DialogueProjection\nglobals\n constant real DIALOGUE_DEPTH = ${p.depth.toFixed(5)}\n constant real DIALOGUE_FRUSTUM_WIDTH = ${p.frustumWidth.toFixed(6)}\n constant real DIALOGUE_CENTER_Y = ${p.centerY.toFixed(6)}\n constant real DIALOGUE_MODEL_WIDTH = ${dialogueModel.width.toFixed(5)}\nendglobals\nendlibrary\n`;}
